// Flourish clips: persistent looping pupil clips (pup_mov_1/pup_mov_2/pup_scale,
// sampled at kIdleRateHz with the duplicate end sample dropped so playback wraps
// to frame 0) and one-shot rotation clips (rot_1..rot_4 at kIdleRateHz,
// rot3d_1/rot3d_2 at 2x). Deltas are additive on top of gaze + idle and start
// (one-shots also end) at zero delta.
struct FlourishClip {
  const char *name;
  std::uint16_t duration_ms;
  std::uint16_t frame_count;
  std::uint16_t time_offset;
  std::uint16_t delta_offset;
  bool wide;  // true: deltas live in the int16 Wide array of the clip's group
};

inline constexpr std::size_t kPupilClipCount = 3;
inline constexpr std::size_t kPupilNarrowFrameCount = 149;
inline constexpr std::size_t kPupilWideFrameCount = 0;

inline constexpr std::array<FlourishClip, kPupilClipCount> kPupilClips{{
    FlourishClip{"pup_mov_1", 4367, 66, 0, 0, false},
    FlourishClip{"pup_mov_2", 2617, 40, 66, 66, false},
    FlourishClip{"pup_scale", 2817, 43, 106, 106, false}
}};

